(function(root){
 'use strict';
 const G={
  levels:[{id:'easy',label:'ง่าย',color:'#32945b'},{id:'skilled',label:'ต้องใช้สัตวบาลชำนาญ',color:'#c18b17'},{id:'aggressive',label:'ดุ อาบไม่ได้',color:'#c24949'},{id:'unknown',label:'ยังไม่ประเมิน',color:'#85928d'}],
  activities:[['bath','อาบน้ำ'],['brush','แปรงขน'],['haircut','ตัดขน'],['nails','ตัดเล็บ'],['ears','ทำความสะอาดหู'],['eyes','ทำความสะอาดตา']],
  month:root.Care.bangkokDate().slice(0,7),currentAtLoad:root.Care.bangkokDate().slice(0,7),building:'all',filter:'pending',query:'',startMonth:'2026-11',
  level(a){return this.levels.find(l=>l.id===a.handlingLevel)||this.levels[3];},
  records(a){return Array.isArray(a.groomingRecords)?a.groomingRecords:[];},
  validDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||'')&&!Number.isNaN(Date.parse(value+'T00:00:00Z'))&&new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;},
  validMonth(value){return /^\d{4}-(0[1-9]|1[0-2])$/.test(value||'');},
  eligible(a,month){return [a.registeredOn,a.birth].filter(v=>this.validDate(v)).every(v=>v.slice(0,7)<=month);},
  bathed(a,month){return this.records(a).some(r=>r.outcome==='completed'&&r.date?.slice(0,7)===month&&r.activities?.includes('bath'));},
  lastBath(a,month=this.month){return this.records(a).filter(r=>r.outcome==='completed'&&r.activities?.includes('bath')&&r.date?.slice(0,7)<=month).sort((a,b)=>b.date.localeCompare(a.date)||String(b.time).localeCompare(String(a.time)))[0]||null;},
  attempts(a,month){return this.records(a).filter(r=>r.outcome==='unable'&&r.date?.slice(0,7)===month).sort((a,b)=>b.date.localeCompare(a.date)||String(b.time).localeCompare(String(a.time)));},
  plan(a,month){return (a.groomingPlans||[]).filter(p=>p.month===month).at(-1)||null;},
  previousMonth(month){const d=new Date(month+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-1);return d.toISOString().slice(0,7);},
  overdue(a,month){const prior=this.previousMonth(month);return month>=this.startMonth&&prior>=this.startMonth&&this.eligible(a,prior)&&!this.bathed(a,prior)&&!this.bathed(a,month);},
  summary(animals,month){const eligible=animals.filter(a=>this.eligible(a,month));return {total:eligible.length,bathed:eligible.filter(a=>this.bathed(a,month)).length,pending:eligible.filter(a=>!this.bathed(a,month)).length,skilled:eligible.filter(a=>!this.bathed(a,month)&&this.level(a).id==='skilled').length,unable:eligible.filter(a=>!this.bathed(a,month)&&(this.level(a).id==='aggressive'||this.attempts(a,month).length)).length,overdue:eligible.filter(a=>this.overdue(a,month)).length};},
  status(a,month){if(this.bathed(a,month))return '✓ อาบแล้ว';if(this.attempts(a,month).length)return 'ทำไม่ได้ · รอติดตาม';if(this.level(a).id==='aggressive')return 'ดุ อาบไม่ได้ · รอวางแผน';if(this.level(a).id==='skilled')return 'รอสัตวบาลชำนาญ';return 'ยังไม่ได้อาบ';},
  record(animal,data,operator,today=root.Care.bangkokDate()){
   if(!animal)throw Error('ไม่พบสัตว์ที่ต้องการบันทึก');
   if(!this.validDate(data.date)||data.date>today||(animal.birth&&data.date<animal.birth))throw Error('กรุณาระบุวันที่ทำจริง ไม่เป็นวันอนาคตหรือก่อนวันเกิด');
   if(!['completed','unable'].includes(data.outcome))throw Error('กรุณาเลือกผลการดูแล');
   const activities=[...new Set(data.activities||[])];
   if(activities.some(v=>!this.activities.some(([id])=>id===v)))throw Error('รายการ Grooming ไม่ถูกต้อง');
   if(data.outcome==='completed'&&!activities.length)throw Error('กรุณากดเลือกสิ่งที่ทำอย่างน้อยหนึ่งรายการ');
   if(data.outcome==='unable'&&(!data.reason?.trim()||!data.nextAction?.trim()))throw Error('กรุณาระบุเหตุผลที่ทำไม่ได้และสิ่งที่จะทำต่อ');
   const r={id:root.crypto.randomUUID(),date:data.date,outcome:data.outcome,activities:data.outcome==='completed'?activities:[],performer:String(data.performer||operator).trim(),reason:data.outcome==='unable'?data.reason.trim():'',nextAction:data.outcome==='unable'?data.nextAction.trim():'',note:String(data.note||'').trim(),operator,time:new Date().toISOString(),kennel:animal.kennel,handlingLevel:this.level(animal).id};
   if([r.reason,r.nextAction,r.note].some(v=>v.length>2000)||r.performer.length>100)throw Error('รายละเอียดหรือชื่อผู้ทำยาวเกินไป');
   animal.groomingRecords=[...this.records(animal),r];return r;
  },
  schedule(animal,data,operator,today=root.Care.bangkokDate()){
   if(!animal)throw Error('ไม่พบสัตว์ที่ต้องการนัดหมาย');
   if(!this.validMonth(data.month)||!this.validDate(data.due)||data.due.slice(0,7)!==data.month||data.due<today)throw Error('เลือกวันนัดตั้งแต่วันนี้ และอยู่ในเดือนที่วางแผน');
   if(!data.assignee?.trim())throw Error('กรุณาระบุผู้รับผิดชอบ');
   if(data.assignee.trim().length>100||String(data.note||'').length>2000)throw Error('รายละเอียดนัดหมายยาวเกินไป');
   const plan={id:root.crypto.randomUUID(),month:data.month,due:data.due,assignee:data.assignee.trim(),note:String(data.note||'').trim(),operator,time:new Date().toISOString()};
   animal.groomingPlans=[...(animal.groomingPlans||[]),plan];return plan;
  },
  badge(a){const l=this.level(a);return `<span class="handling-badge handling-${l.id}"><i style="background:${l.color}"></i>${esc(l.label)}</span>`;},
  tick(a,month=root.Care.bangkokDate().slice(0,7)){return this.bathed(a,month)?`<span class="bath-tick" title="อาบน้ำแล้ว ${esc(month)}" aria-label="อาบน้ำแล้วเดือน ${esc(month)}">✓</span>`:'';},
  handlingFields(a={}){return `<fieldset class="field wide handling-field"><legend>ระดับการจับดูแล</legend><div class="groom-chips">${this.levels.map(l=>`<label class="groom-choice handling-${l.id}"><input type="radio" name="handlingLevel" value="${l.id}" ${this.level(a).id===l.id?'checked':''}><span><i style="background:${l.color}"></i>${l.label}</span></label>`).join('')}</div></fieldset><label class="field">สัตวบาล / ผู้ที่จับได้<input name="handlingPerson" maxlength="100" value="${esc(a.handlingPerson||'')}" placeholder="ระบุชื่อ ถ้ามี"></label><label class="field">ข้อควรทราบ / จำนวนคนช่วย<input name="handlingNote" maxlength="1000" value="${esc(a.handlingNote||'')}" placeholder="เช่น ต้องช่วยกัน 2 คน"></label>`;},
  profile(a){const month=root.Care.bangkokDate().slice(0,7),last=this.lastBath(a,month),plan=this.plan(a,month);return `<section class="profile-section groom-profile"><h3>อาบน้ำและ Grooming</h3><div class="groom-profile-meta">${this.badge(a)} ${this.tick(a)} <strong>${this.status(a,month)}</strong></div><p class="side-copy">อาบล่าสุด: ${last?thaiDate(last.date):'ยังไม่มีประวัติอาบน้ำที่บันทึก'}${last?' · '+esc(last.performer):''}</p>${a.handlingPerson||a.handlingNote?`<div class="profile-box">${esc(a.handlingPerson||'')} ${esc(a.handlingNote||'')}</div>`:''}${plan?`<p class="side-copy">นัด ${thaiDate(plan.due)} · ${esc(plan.assignee)}</p>`:''}<div class="groom-row-actions"><button class="primary" data-groom="record" data-id="${esc(a.id)}" data-month="${month}">บันทึกอาบน้ำ / Grooming</button><button class="secondary" data-groom="plan" data-id="${esc(a.id)}" data-month="${month}">นัดหมาย / มอบหมาย</button></div><details class="groom-history"><summary>ประวัติย้อนหลัง (${this.records(a).length} ครั้ง)</summary>${this.history(a)}</details></section>`;},
  history(a){return [...this.records(a)].sort((a,b)=>b.date.localeCompare(a.date)||String(b.time).localeCompare(String(a.time))).map(r=>`<div class="med-item"><strong>${thaiDate(r.date)} · ${r.outcome==='unable'?'ยังทำไม่ได้':this.activities.filter(([id])=>r.activities.includes(id)).map(([,label])=>label).join(' / ')}</strong><div>${esc(r.performer)} · บันทึกโดย ${esc(r.operator)}</div>${r.reason?`<div>เหตุผล: ${esc(r.reason)}<br>สิ่งที่จะทำต่อ: ${esc(r.nextAction)}</div>`:''}${r.note?`<div>${esc(r.note)}</div>`:''}<small>คอกขณะบันทึก ${esc(r.kennel)} · ${thaiDate(r.time,true)}</small></div>`).join('')||'<p class="side-copy">ยังไม่มีประวัติ Grooming</p>';},
  render(){
   const current=root.Care.bangkokDate().slice(0,7);if(this.month===this.currentAtLoad){this.month=current;this.currentAtLoad=current;}
   const eligible=state.animals.filter(a=>this.eligible(a,this.month)),all=this.summary(eligible,this.month);
   const groups=[...Care.buildings.map(id=>['D'+id+'-',`คอกสุนัข ${id}${id===5?' (คลินิก)':''}`]),['other','ตำแหน่งอื่น / รอยืนยันคอก']];
   const rows=eligible.filter(a=>(this.building==='all'||(this.building==='other'?!Care.kennels.includes(a.kennel):a.kennel.startsWith(this.building)))&&(`${a.name} ${Care.animalCode(a)} ${a.kennel} ${a.breed||''}`.toLowerCase().includes(this.query.toLowerCase()))&&(this.filter==='all'||this.filter==='bathed'&&this.bathed(a,this.month)||this.filter==='pending'&&!this.bathed(a,this.month)||this.filter==='skilled'&&!this.bathed(a,this.month)&&this.level(a).id==='skilled'||this.filter==='unable'&&!this.bathed(a,this.month)&&(this.level(a).id==='aggressive'||this.attempts(a,this.month).length)||this.filter==='overdue'&&this.overdue(a,this.month)||this.filter==='unknown'&&this.level(a).id==='unknown'));
   const groupHTML=groups.map(([prefix,label])=>{const animals=rows.filter(a=>prefix==='other'?!Care.kennels.includes(a.kennel):Care.kennels.includes(a.kennel)&&a.kennel.startsWith(prefix));if(!animals.length)return '';const allInGroup=eligible.filter(a=>prefix==='other'?!Care.kennels.includes(a.kennel):Care.kennels.includes(a.kennel)&&a.kennel.startsWith(prefix)),summary=this.summary(allInGroup,this.month);const kennels=[...new Set(animals.map(a=>a.kennel))].sort();return `<section class="groom-building"><div class="section-title"><h2>${label}</h2><span class="side-copy">อาบแล้ว ${summary.bathed}/${summary.total} ตัว</span></div>${kennels.map(code=>`<section class="card groom-kennel"><h3>${esc(code)}</h3>${animals.filter(a=>a.kennel===code).sort((a,b)=>a.name.localeCompare(b.name,'th')).map(a=>this.row(a)).join('')}</section>`).join('')}</section>`;}).join('');
   return heading('','อาบน้ำและ Grooming','ติดตามการอาบน้ำอย่างน้อยเดือนละ 1 ครั้ง แยกตามคอก',`<label class="month-control"><input type="month" id="groom-month" aria-label="เดือนที่ติดตามอาบน้ำ" value="${this.month}" max="${root.Care.bangkokDate().slice(0,7)}"></label>`)+`<div class="groom-stats">${[[all.bathed,'อาบแล้ว','bathed'],[all.pending,'ยังไม่ได้อาบ','pending'],[all.skilled,'รอสัตวบาลชำนาญ','skilled'],[all.unable,'ทำไม่ได้ / รอวางแผน','unable'],[all.overdue,'ไม่มีบันทึกเดือนก่อน','overdue']].map(([count,label,filter])=>`<button class="card groom-stat ${this.filter===filter?'selected':''}" data-groom="filter" data-filter="${filter}"><strong>${count}</strong><span>${label}</span></button>`).join('')}</div><p class="side-copy">จากสัตว์ ${all.total} ตัวในทะเบียน · ✓ นับเฉพาะบันทึกอาบน้ำเสร็จในเดือนที่เลือก · สถานะรอผู้ชำนาญและทำไม่ได้เป็นส่วนหนึ่งของรายการยังไม่ได้อาบ</p><div class="search animal-filters"><input type="search" id="groom-search" aria-label="ค้นหาสัตว์เพื่อ Grooming" placeholder="ค้นหาชื่อ รหัส หรือคอก" value="${esc(this.query)}"><select id="groom-building" aria-label="กรองคอกอาบน้ำ"><option value="all">ทุกคอก</option>${groups.map(([value,label])=>`<option value="${value}" ${this.building===value?'selected':''}>${label}</option>`).join('')}</select><select id="groom-filter" aria-label="กรองสถานะอาบน้ำ">${[['pending','ยังไม่ได้อาบ'],['all','ทุกตัว'],['bathed','อาบแล้ว'],['skilled','รอสัตวบาลชำนาญ'],['unable','ทำไม่ได้ / รอวางแผน'],['overdue','ไม่มีบันทึกเดือนก่อน'],['unknown','ยังไม่ประเมินการจับ']].map(([value,label])=>`<option value="${value}" ${this.filter===value?'selected':''}>${label}</option>`).join('')}</select></div><p class="side-copy">แสดง ${rows.length} ตัว · รายงาน Excel ใช้เดือนที่เลือกในหน้านี้ · ข้อมูลก่อนเริ่มระบบเดือนพฤศจิกายน 2569 ที่ยังไม่บันทึก ไม่ได้ยืนยันว่าไม่ได้อาบ</p>${groupHTML||'<section class="card empty-state">ไม่พบสัตว์ที่ตรงกับตัวกรอง</section>'}<details class="groom-history groom-legacy"><summary>งานดูแลเดิม (${state.tasks.length} รายการ)</summary>${renderLegacyTasks()}</details>`;
  },
  row(a){const month=this.month,last=this.lastBath(a,month),attempt=this.attempts(a,month)[0],plan=this.plan(a,month);return `<div class="groom-animal"><div class="groom-animal-main"><button class="text-link" data-action="profile" data-id="${esc(a.id)}">${this.tick(a,month)}<strong>${esc(a.name)}</strong></button><div class="row-sub">${esc(Care.animalCode(a)||'ไม่ระบุรหัส')} · ${esc(a.breed||'ไม่ระบุพันธุ์')}</div>${this.badge(a)}<p class="side-copy">${this.status(a,month)}<br>อาบล่าสุด: ${last?thaiDate(last.date)+' · '+esc(last.performer):'ยังไม่มีประวัติที่บันทึก'}${this.overdue(a,month)?'<br><span class="danger-text">ไม่มีบันทึกอาบน้ำในเดือนก่อน</span>':''}</p>${attempt?`<div class="groom-attempt">${thaiDate(attempt.date)} ทำไม่ได้: ${esc(attempt.reason)}<br>ต่อไป: ${esc(attempt.nextAction)}</div>`:''}${a.handlingPerson||a.handlingNote?`<p class="side-copy">${esc(a.handlingPerson||'')} ${esc(a.handlingNote||'')}</p>`:''}${plan?`<p class="groom-plan">นัด ${thaiDate(plan.due)} · ${esc(plan.assignee)}${plan.note?'<br>'+esc(plan.note):''}</p>`:''}</div><div class="groom-row-actions"><button class="primary" data-groom="record" data-id="${esc(a.id)}" data-month="${month}">บันทึกสิ่งที่ทำ</button><button class="secondary" data-groom="plan" data-id="${esc(a.id)}" data-month="${month}">นัด / มอบหมาย</button><button class="text-link" data-action="edit-animal" data-id="${esc(a.id)}">แก้ระดับการจับ</button></div></div>`;},
  form(id,type,month=this.month){const a=findAnimal(id);if(!a)return;const today=root.Care.bangkokDate(),current=today.slice(0,7);if(type==='plan'&&month<current)month=current;const plan=this.plan(a,month);const fields=type==='plan'?`<label class="field">เดือนที่วางแผน<input type="month" name="month" value="${month}" min="${current}" required></label><label class="field">วันนัด<input type="date" name="due" value="${plan&&plan.due>=today?plan.due:month===current?today:month+'-01'}" min="${today}" required></label><label class="field wide">ผู้รับผิดชอบ *<input name="assignee" value="${esc(plan?.assignee||a.handlingPerson||'')}" maxlength="100" required></label>`:`<label class="field">วันที่ทำจริง *<input name="date" type="date" value="${month<current?'':today}" max="${today}" required></label><label class="field">ผู้ทำ<input name="performer" value="${esc(cloud.enabled?cloud.member.name:state.operator)}" maxlength="100" required></label><fieldset class="field wide"><legend>ผลการดูแล</legend><div class="groom-chips"><label class="groom-choice"><input type="radio" name="outcome" value="completed" checked><span>ทำแล้ว</span></label><label class="groom-choice"><input type="radio" name="outcome" value="unable"><span>ยังทำไม่ได้</span></label></div></fieldset><fieldset class="field wide" id="groom-activities"><legend>กดเลือกสิ่งที่ทำแล้ว</legend><div class="groom-chips">${this.activities.map(([key,label])=>`<label class="groom-choice"><input type="checkbox" name="activities" value="${key}"><span>${label}</span></label>`).join('')}</div></fieldset><div class="wide" id="groom-unable" hidden><label class="field">เหตุผลที่ทำไม่ได้ *<textarea name="reason" maxlength="2000" placeholder="เช่น จับไม่ได้ / รอสัตวบาลชำนาญ"></textarea></label><label class="field">สิ่งที่จะทำต่อ *<textarea name="nextAction" maxlength="2000" placeholder="ระบุผู้ที่ต้องประสานหรือแผนครั้งถัดไป"></textarea></label><p class="side-copy">รายการนี้จะไม่ถูกนับว่าอาบแล้ว หากทำบางรายการสำเร็จ ให้บันทึกสิ่งที่ทำแล้วแยกอีกครั้ง</p></div>`;
   openModal(type==='plan'?'นัดหมาย / มอบหมาย · '+a.name:'บันทึกอาบน้ำ / Grooming · '+a.name,`<form data-groom-form="${type}" data-id="${esc(id)}"><div class="modal-body"><div class="error" role="alert"></div>${this.badge(a)}<p class="side-copy">${esc(Care.animalCode(a)||'ไม่ระบุรหัส')} · ${esc(a.kennel)}${a.handlingNote?' · '+esc(a.handlingNote):''}</p><div class="form-grid">${fields}<label class="field wide">หมายเหตุ<textarea name="note" maxlength="2000">${esc(type==='plan'?plan?.note||'':'')}</textarea></label></div></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">ยกเลิก</button><button class="primary" type="submit">บันทึก</button></div></form>`);
  }
 };
 root.Groom=G;if(typeof module!=='undefined')module.exports=G;
 if(typeof document==='undefined')return;
 document.addEventListener('click',e=>{const el=e.target.closest('[data-groom]');if(!el)return;const action=el.dataset.groom;if(action==='filter'){G.filter=el.dataset.filter;render();}else if(action==='record'||action==='plan')G.form(el.dataset.id,action,el.dataset.month||root.Care.bangkokDate().slice(0,7));});
 document.addEventListener('input',e=>{if(e.target.id==='groom-search'){G.query=e.target.value;const pos=e.target.selectionStart;render();const field=document.getElementById('groom-search');field.focus();field.setSelectionRange(pos,pos);}});
 document.addEventListener('change',e=>{const el=e.target;if(el.id==='groom-month'){if(G.validMonth(el.value)&&el.value<=root.Care.bangkokDate().slice(0,7)){G.month=el.value;render();}else el.value=G.month;}else if(el.id==='groom-building'||el.id==='groom-filter'){G[el.id==='groom-building'?'building':'filter']=el.value;render();}else if(el.name==='outcome'&&el.closest('form[data-groom-form]')){const form=el.closest('form'),unable=el.value==='unable';form.querySelector('#groom-unable').hidden=!unable;form.querySelector('#groom-activities').hidden=unable;for(const name of ['reason','nextAction'])form.querySelector(`[name="${name}"]`).required=unable;}});
 document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-groom-form]');if(!form)return;e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;
  try{const values=new FormData(form),data=Object.fromEntries(values),operator=cloud.enabled?cloud.member.name:state.operator;if(!operator)throw Error('กรุณาระบุผู้บันทึก');data.activities=values.getAll('activities');const draft=structuredClone(state),animal=draft.animals.find(a=>a.id===form.dataset.id);let text;
   if(form.dataset.groomForm==='plan'){const p=G.schedule(animal,data,operator);text=`นัด Grooming ${animal.name}: ${p.due} · ${p.assignee}`;}else{const r=G.record(animal,data,operator);text=`Grooming ${animal.name} ${r.date}: ${r.outcome==='unable'?'ทำไม่ได้ · '+r.reason+' · ต่อไป: '+r.nextAction:G.activities.filter(([id])=>r.activities.includes(id)).map(([,label])=>label).join(' / ')} · ผู้ทำ ${r.performer}`;}
   addEvent(draft,text,operator);await commit(draft);dialog.close();toast('บันทึกเรียบร้อย');
  }catch(error){const box=form.querySelector('.error');box.textContent=error.message;box.scrollIntoView({block:'nearest'});}finally{button.disabled=false;}
 });
})(typeof globalThis!=='undefined'?globalThis:this);
